# v622: the Glyph Wheel reworked: the owner's recorded sounds, buzz, an honest slow crawl, streak, lucky meter, glyph sets, Lucky Hour
# and a shared jackpot pot. See p622_wheel.js and supabase/v622_wheel_pool.sql.
import sys, re
P = sys.argv[1] if len(sys.argv) > 1 else 'docs/index.html'
s = open(P, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (c, a[:90]); s = s.replace(a, b)
js = open('tools/patches/p622_wheel.js', encoding='utf-8').read()
css = ('.gwm{display:grid;gap:6px;margin:8px 0 2px;text-align:left;letter-spacing:normal}.gwm *{letter-spacing:normal!important}.gwmg{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}'
       '.gwc{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0;background:rgba(255,255,255,.04);border:1px solid rgba(255,214,110,.16);border-radius:10px;padding:5px 8px}.gwc[hidden]{display:none}'
       '.gwc>span{font-size:9.5px!important;letter-spacing:.08em!important;text-transform:uppercase;color:#e2cf94}.gwc>small{font-size:10.5px;opacity:.8;line-height:1.25}'
       '.gwdots{display:flex;gap:4px;align-items:center;height:16px}.gwdots em{width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,.14)}.gwdots em.on{background:#ffcf5a;box-shadow:0 0 7px #ffcf5a}.gwdots em.big{width:14px;height:14px;border:1.5px solid #ff6ad5}.gwdots em.big.on{background:#ff6ad5;box-shadow:0 0 9px #ff6ad5}'
       '.gwbar{display:block;width:100%;height:8px;margin:4px 0;border-radius:5px;background:rgba(255,255,255,.1);overflow:hidden}.gwbar b{display:block;height:100%;background:linear-gradient(90deg,#7af4ff,#ff6ad5);box-shadow:0 0 8px #ff6ad5}'
       '.gwgl{display:flex;gap:4px;font-style:normal}.gwgl em{font-style:normal;width:20px;height:20px;display:grid;place-items:center;border-radius:5px;background:rgba(255,255,255,.07);color:rgba(255,255,255,.35);font-size:13px}.gwgl em.on{background:rgba(255,207,90,.22);color:#ffcf5a;text-shadow:0 0 6px #ffcf5a}'
       '.arimg.big{max-height:min(40vh,360px);cursor:zoom-in}.arimg.big:not(.ship) img{height:min(40vh,360px)!important;object-fit:cover!important;object-position:50% 18%}.arimg.big.ship img{height:min(40vh,360px)!important}.arimg.big.open{max-height:none;cursor:zoom-out}.arimg.big.open img{height:auto!important;max-height:none;object-fit:contain!important}'
       '.arimg.big::after{content:"⤢ tap to see it all";position:absolute;right:8px;bottom:8px;font-size:11px;padding:3px 8px;border-radius:8px;background:rgba(0,0,0,.6);color:#e2c48a;pointer-events:none}.arimg.big.open::after{content:"⤡ tap to shrink"}'
       '.bag{position:relative;width:32px;height:32px;border-radius:50%;background:#1d1430;border:1px solid #8f6cff;color:#e8dcff;display:grid;place-items:center;cursor:pointer;padding:0}.bag svg{width:17px;height:17px}.bag i{position:absolute;top:-5px;right:-6px;min-width:16px;height:16px;border-radius:8px;background:#ffcf5a;color:#1a1020;font:700 9.5px/16px var(--f-display);font-style:normal;padding:0 3px;box-sizing:border-box;text-align:center}'
       '.gwpv{font-size:15px;color:#ff8ae0;text-shadow:0 0 8px #ff6ad5}.gwlh{background:linear-gradient(90deg,#ff6ad5,#ffcf5a);color:#1a0f20;font-weight:700;border-radius:10px;padding:5px 10px;font-size:12px;text-align:center;animation:gwlh 1.6s ease-in-out infinite}@keyframes gwlh{50%{filter:brightness(1.25)}}\n')
i = s.index('</style>', s.index('#celeb{position:fixed')); s = s[:i] + css + s[i:]
a = s.index('function wheelHTML(T) {'); s = s[:a] + js + '\ndocument.addEventListener("click", e => { const a = e.target && e.target.closest && e.target.closest(".arimg.big"); if (a) a.classList.toggle("open"); }); /* v622 a record\'s painting fits the page; tap it to see it whole */\n' + s[a:]
rep('<div class="gwchips">${chips}</div>', '${whlMeters()}<div class="gwchips">${chips}</div>')
rep('function whlStart() { if (G.whlRaf || !document.getElementById("gwslot")) return;', 'function whlStart() { try { wsLoad(); whlPotLoad(); } catch (e) {} if (G.whlRaf || !document.getElementById("gwslot")) return;')
# the pull: the recorded lever and spin-up, then the pick with the streak, the lucky meter and Lucky Hour
rep('if (G.wheel || (!G.owner && !free && !bon && !paid) || S.wheelPend != null) return; try { WSFX.lever(); } catch (e) {}\n  let r = Math.random() * WHEEL.reduce((a, W) => a + W.w, 0), idx = 0; for (let i = 0; i < WHEEL.length; i++) { r -= WHEEL[i].w; if (r < 0) { idx = i; break; } }',
    'if (G.wheel || (!G.owner && !free && !bon && !paid) || S.wheelPend != null) return; try { wsLoad(); if (!wsPlay("lever")) WSFX.lever(); if (AU.ctx) wsPlay("spin", AU.ctx.currentTime + .3); whlBuzz(18); } catch (e) {}\n'
    '  const d0 = whlDay(), st0 = S.whlStk || {}, sN = free && !G.owner ? (st0.d === d0 - 1 ? (st0.n || 0) + 1 : st0.d === d0 ? st0.n || 0 : 1) : null, why = sN != null && sN >= 7 ? "streak" : (S.whlLk || 0) >= WHL_LK_MAX ? "lucky" : null; let idx = whlPick(!!why); /* v622 */')
rep('G.wheel = { from, to, t0: performance.now(), dur: 6400, idx, peg: null };', 'const crawl = WHL_RARE(WHEEL[idx]); G.wheel = { from, to, t0: performance.now(), dur: crawl ? 8600 : 6400, crawl, idx, peg: null }; /* v622 only a real rare prize crawls over the last pegs */')
rep('S.wheelPend = idx; bump("wheelSpins"); }); crumb("glyph wheel spun");', 'S.wheelPend = idx; bump("wheelSpins"); if (sN != null) S.whlStk = { d: d0, n: sN >= 7 ? 0 : sN }; S.whlLk = WHL_RARE(WHEEL[idx]) ? 0 : (S.whlLk || 0) + 1; G.whlWhy = why; }); crumb("glyph wheel spun");\n'
    '  try { if (window.udfWheel && G.mode === "online" && !G.owner) window.udfWheel.spin(1).then(p => { if (G.whlPS && typeof p === "number") { G.whlPS.pool = p; whlPotPaint(); } }).catch(() => {}); } catch (e) {}')
rep('(1 - Math.pow(1 - v, 4.4))', '(1 - Math.pow(1 - v, R.crawl ? 5.6 : 4.4))')
rep('try { WSFX.tick(G.whlA ? G.whlA.v : 300); } catch (er) {}', 'try { const v = G.whlA ? G.whlA.v : 300; if (!wsPlay("tick", 0, .75 + .25 * Math.min(1, v / 900), 1 + .22 * (1 - Math.min(1, v / 700)))) WSFX.tick(v); if (n - (R.bz || 0) > 70) { R.bz = n; whlBuzz(5); } } catch (er) {}')
rep('G.whlBurst = R.idx; wheelGrant(); }', 'G.whlBurst = R.idx; try { wsPlay("land"); whlBuzz(28); } catch (e) {} wheelGrant(); }')
# the prize: the glyph set, the recorded win sounds, the reasons it was sure, and the shared pot
rep('act(() => { S.wheelPend = null; if (W.k === "sh") S.shards = (S.shards || 0) + W.n; else giveItem(W.k); });',
    'let setDone = false; act(() => { S.wheelPend = null; if (W.k === "sh") S.shards = (S.shards || 0) + W.n; else giveItem(W.k); const gs = whlGlyphs(); if (!gs.done && gs.set.includes(W.g) && !gs.got.includes(W.g)) { S.whlGs = { wk: gs.wk, got: gs.got.concat(W.g), done: 0 }; if (S.whlGs.got.length >= gs.set.length) { S.whlGs.done = 1; S.shards = (S.shards || 0) + WHL_SET_PAY; setDone = true; } } }); /* v622 */')
rep('try { W.jack ? WSFX.jackpot(W.jack === 2) : WSFX.win(W.w <= 2.5 ? 1 : 0); } catch (e) {}',
    'try { const k = W.jack === 2 ? "mega" : W.jack ? "jack" : W.w <= 2.5 ? "rare" : "win"; if (!wsPlay(k, AU.ctx ? AU.ctx.currentTime + .15 : 0)) (W.jack ? WSFX.jackpot(W.jack === 2) : WSFX.win(W.w <= 2.5 ? 1 : 0)); if (W.jack) whlBuzz([70, 40, 70, 40, 200]); else if (W.w <= 2.5) whlBuzz([40, 30, 90]); } catch (e) {}\n'
    '  try { const why = G.whlWhy; G.whlWhy = null; if (why === "streak") setTimeout(() => { toast("Day 7 of your streak: a sure rare prize. The streak starts again tomorrow.", "win"); advHolo("Seven days running, Commander. The glyphs owed you that one.", true); }, 1800); else if (why === "lucky") setTimeout(() => { toast("The lucky meter was full: a sure rare prize.", "win"); advHolo("The lucky meter was full. I told you the wheel remembers.", true); }, 1800);\n'
    '    if (setDone) setTimeout(() => { toast(`Glyph set complete! ◆${WHL_SET_PAY} for this week\'s five glyphs.`, "win"); advHolo("All five glyphs of the week. Well spun, Commander.", true); try { WSFX.coins(1, 20); } catch (e) {} render(true); }, why ? 4200 : 1600); } catch (e) {}\n'
    '  try { if (W.jack && window.udfWheel && G.mode === "online" && !G.owner) window.udfWheel.win(W.jack === 2 ? "mega" : "jack", G.myName || S.homeName || "A commander").then(a => { if (a > 0) { act(() => { S.shards = (S.shards || 0) + a; }); setTimeout(() => toast(`+◆${fmt(a)} from the shared pot!`, "win"), 2600); } whlPotLoad(true); }).catch(() => {}); } catch (e) {}')
# the bag: your items one tap away, from the top bar on every screen
rep('<button class="snd" data-act="soundPanel" aria-label="Sound and volume${AU.muted ? ", muted" : ""}">', '${(() => { const n = Object.values(S.items || {}).filter(v => v > 0).length; return `<button class="bag" data-act="invOpen" aria-label="Your items: ${n}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M5 8h14l-1.2 12.2a1 1 0 0 1-1 .8H7.2a1 1 0 0 1-1-.8z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></svg>${n ? `<i>${n > 99 ? "99+" : n}</i>` : ""}</button>`; })()}<button class="snd" data-act="soundPanel" aria-label="Sound and volume${AU.muted ? ", muted" : ""}">')
rep('  targets: () => { sub.gal = sub.gal || "targets"; openSheet({ type: "targets" }); },', '  invOpen: () => { closeSheet(); openSheet({ type: "shop", cat: "inv", noIntro: 1 }); }, /* v622 the bag in the top bar */\n  targets: () => { sub.gal = sub.gal || "targets"; openSheet({ type: "targets" }); },')
s2 = re.sub(r"GAME_V = 621\b", "GAME_V = 622", s); assert s2 != s; s = s2
open(P, 'w', encoding='utf-8').write(s); print('ok')
